import { test, expect } from '@playwright/test';

test.describe('Cancel In-Progress File Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should successfully cancel an in-progress file upload', async ({ page }) => {
    // Setup: intercept the upload API
    await page.route('**/api/upload', (route) => {
      route.abort('failed');
    });

    // Setup: intercept the cancel API
    await page.route('**/api/upload/cancel', (route) => {
      route.continue();
    });

    // Setup: intercept the success API
    await page.route('**/api/upload/success', (route) => {
      route.continue();
    });

    // Setup: intercept the error API
    await page.route('**/api/upload/error', (route) => {
      route.continue();
    });

    // Upload file using getByLabel
    const uploadInput = page.getByLabel('Upload file');
    await uploadInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Verify upload progress indicator appears
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify upload status text
    const statusText = page.getByText('Uploading...');
    await expect(statusText).toBeVisible();

    // Click cancel button using getByRole
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Verify cancel confirmation dialog appears
    const confirmDialog = page.getByRole('dialog', { name: /confirm cancellation/i });
    await expect(confirmDialog).toBeVisible();

    // Click confirm button using getByRole
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await confirmButton.click();

    // Verify upload is cancelled
    await expect(statusText).not.toBeVisible();
    await expect(page.getByText('Upload cancelled')).toBeVisible();
    await expect(progressBar).not.toBeVisible();
  });

  test('should handle cancellation when upload is already complete', async ({ page }) => {
    // Setup: intercept the upload API and return success
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Setup: intercept the cancel API
    await page.route('**/api/upload/cancel', (route) => {
      route.continue();
    });

    // Upload file using getByLabel
    const uploadInput = page.getByLabel('Upload file');
    await uploadInput.setInputFiles('playwright/fixtures/sample.pdf');

    // Wait for upload to complete
    await page.waitForTimeout(1000);

    // Verify upload success message
    const successMessage = page.getByText('Upload complete');
    await expect(successMessage).toBeVisible();

    // Verify success status
    const statusText = page.getByText('Success');
    await expect(statusText).toBeVisible();

    // Click cancel button using getByRole
    const cancelButton = page.getByRole('button', { name: /cancel/i });
    await cancelButton.click();

    // Verify cancel confirmation dialog appears
    const confirmDialog = page.getByRole('dialog', { name: /confirm cancellation/i });
    await expect(confirmDialog).toBeVisible();

    // Click confirm button using getByRole
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await confirmButton.click();

    // Verify cancellation message
    await expect(page.getByText('Upload cancelled')).toBeVisible();
    await expect(successMessage).not.toBeVisible();
  });
});
